-- Wrong-entity Wikidata links on unified_tags — the namesake chimera at glossary scale.
--
-- MEASURED, 2026-08-29. `tag-enrichment-sweep` resolves a tag's Wikidata id by
-- fetching en.wikipedia.org/api/rest_v1/page/summary/<RAW TAG NAME> and adopting
-- whatever `wikibase_item` comes back. Only a disambiguation PAGE is skipped, so a
-- REDIRECT to a real article passes: `Golden shower` → `Cassia_fistula`,
-- `Passing` → `Death`, `Amateur` → `Indianapolis`, `Anal` → `Analyst` (a journal).
-- `wikipedia_url` on those rows is literally the redirect target, which is the proof.
--
-- Of 4,772 tags carrying a wikidata_id, 1535 point at an entity of a class a
-- glossary term can never be — a scholarly article or journal, a given/family name, a
-- taxon, a disambiguation page, a film/album/song/video game, a settlement, a piece of
-- software, a ship. Measured by pulling every stored QID through wbgetentities and
-- classifying its P31, then cross-tabbing against the tag's own category so the cells
-- where a foreign class is legitimate (Destinations×place, People & Icons×person,
-- Media & Entertainment×media) are exempt. Hand-read stratified samples: 45/45 of the
-- structural classes were genuine defects, 30/30 on a second draw after two regex
-- false positives were removed (`tomboy`→stock character, `damsel in distress`→cliché
-- were being read as media, and `voice acting`→"business sector" as an org).
--
-- THE PROSE MAY NOT VOUCH FOR THE LINK. On this corpus `short_description` and
-- `long_description` were generated FROM the wrong entity, so token overlap between a
-- tag's own prose and the wrong entity's description is contamination, not evidence —
-- the first draft of this rule used overlap as corroboration and kept `disco`→Discogs,
-- `spa`→the Spanish language and `seafood`→COVID-19 because their prose had already
-- been overwritten to match. Only `legit-category` may rescue a foreign class.
--
-- THE CONCEPT CLASS IS DELIBERATELY NOT AUTO-CLEARED. A QID that is at least a concept
-- may legitimately be broader or narrower than the tag (`soccer`→association football,
-- `accessible`→accessibility, `ethical-non-monogamy`→consensual non-monogamy). Auto-
-- clearing that bucket was measured to destroy roughly 70% correct links to remove a
-- minority of wrong ones, so its 267 mismatches are RECORDED FOR REVIEW and left
-- untouched. 21 rows in it were read by hand and are cleared here with a per-row
-- reason, because prose contamination made the automated rule keep them and four of
-- them publish clinical codes.
--
-- CLINICAL CODES ARE THE SHARPEST HARM, same shape as `trauma` in the 2026-08 health
-- pass: `passing` (a trans glossary entry) resolved to Q4 **death** and published
-- ICPC-2 A96; `seafood` resolved to Q84263196 **COVID-19** and published U07.1, U07.2
-- and SNOMED 840539006; `bearded` resolved to hirsutism and published L68.0; `s-a-m`
-- to the United States. `tag_medical_codes`, the wikidata-derived `broader` edges in
-- `tag_relations` and the wikipedia/wikidata `tag_sources` rows all key off this
-- identifier and are regenerated weekly, so clearing prose without clearing the QID
-- would rebuild the wrong data — the exact failure of the health-tag pass, which fixed
-- seven paragraphs and left six wrong QIDs in place.
--
-- PREFER NULL TO A GUESS. Nothing is re-resolved here; a plausible-but-wrong QID
-- regenerates wrong data every week, and a null one regenerates nothing. Every prior
-- value is snapshotted in `tag_wikidata_repair_audit` and the full row in
-- `tag_change_log`, so this is reversible.
--
-- RELATION TO 20261007160200_tag_wikidata_chimera_retraction. A concurrent session
-- hand-read 44 of these rows and retracted their bodies the same week (`passing`,
-- `seafood`, `flogger`→a MiG-23, `public`→PubMed). That pass and this one are the same
-- defect at two scales: it judged by reading each row, which is why it is right about
-- prose on rows this rule cannot reason about, and stopped at 44; this one judges by
-- the entity's P31 class, which scales to the whole corpus but cannot tell a good
-- paragraph from a bad one. They compose because this migration re-checks the LIVE
-- identifier against the one it audited and drops any row that has moved since —
-- measured against the real apply order, 25 rows are skipped for exactly that reason
-- and nothing is repaired twice. Zero of the e2e fixtures overlap, so each pass is
-- guarded by cases only it fixes.
--
-- Producer sealed in the same change: `tag-enrichment-sweep` now requires the resolved
-- Wikipedia title to agree with the tag name, or the tag's own description to
-- corroborate the extract on vocabulary that is not the tag's own name. Without that,
-- the cohort regrows on the next cron pass.

create table if not exists public.tag_wikidata_repair_audit (
  tag_id                     uuid primary key references public.unified_tags(id) on delete cascade,
  disposition                text not null check (disposition in ('cleared','review')),
  previous_wikidata_id       text,
  previous_wikipedia_url     text,
  previous_short_description text,
  previous_long_description  text,
  wikidata_label             text,
  wikidata_description       text,
  wikidata_class             text,
  reason                     text,
  repaired_at                timestamptz not null default now()
);
comment on table public.tag_wikidata_repair_audit is
  'Snapshot of every unified_tags row whose wikidata_id was cleared (or flagged for review) by the 2026-08-29 wrong-entity repair. The only record of the previous identifier and of any prose retracted with it; disposition=''review'' rows were NOT modified.';

alter table public.tag_wikidata_repair_audit enable row level security;
revoke all on table public.tag_wikidata_repair_audit from anon, authenticated;
grant select, insert, update, delete on table public.tag_wikidata_repair_audit to service_role;

do $repair$
declare
  v_cleared int; v_review int; v_short int; v_long int;
  v_codes int; v_rel int; v_src int; v_missing int;
begin
  -- log_unified_tag_change() refuses a system:% actor on a human_reviewed row, and
  -- 586 of these rows carry that flag — a human reviewed the prose and the wrong
  -- identifier underneath it survived the review.
  perform set_config('app.actor', 'migration:20261008100000_tag_wrong_entity_wikidata_repair', true);

  create temp table _repair (
    tag_id uuid primary key, disposition text, qid text, label text,
    wdesc text, class text, reason text, clear_short boolean, clear_long boolean
  ) on commit drop;


  -- A row whose stored QID has moved on since the audit is left alone rather than
  -- cleared on stale evidence: the identifier is the thing being judged.
  delete from _repair r
   using public.unified_tags u
   where u.id = r.tag_id
     and u.wikidata_id is distinct from r.qid;
  get diagnostics v_missing = row_count;

    tag_id, disposition, previous_wikidata_id, previous_wikipedia_url,
    previous_short_description, previous_long_description,
    wikidata_label, wikidata_description, wikidata_class, reason)
  select u.id, r.disposition, u.wikidata_id, u.wikipedia_url,
         case when r.clear_short then u.short_description end,
         case when r.clear_long  then u.long_description  end,
         r.label, r.wdesc, r.class, r.reason
    from _repair r join public.unified_tags u on u.id = r.tag_id
  on conflict (tag_id) do update set
    disposition = excluded.disposition,
    previous_wikidata_id = excluded.previous_wikidata_id,
    previous_wikipedia_url = excluded.previous_wikipedia_url,
    previous_short_description = coalesce(excluded.previous_short_description, tag_wikidata_repair_audit.previous_short_description),
    previous_long_description  = coalesce(excluded.previous_long_description,  tag_wikidata_repair_audit.previous_long_description),
    wikidata_label = excluded.wikidata_label,
    wikidata_description = excluded.wikidata_description,
    wikidata_class = excluded.wikidata_class,
    reason = excluded.reason,
    repaired_at = now();

  -- One UPDATE, not three: trg_search_documents_tag is scoped to short_description
  -- among others, so every extra statement re-enqueues the same row.
  update public.unified_tags u
     set wikidata_id       = null,
         wikipedia_url     = null,
         short_description = case when r.clear_short then null else u.short_description end,
         long_description  = case when r.clear_long  then null else u.long_description  end,
         updated_at        = now()
    from _repair r
   where r.tag_id = u.id and r.disposition = 'cleared';
  get diagnostics v_cleared = row_count;

  select count(*) filter (where clear_short), count(*) filter (where clear_long),
         count(*) filter (where disposition = 'review')
    into v_short, v_long, v_review
    from _repair;

  -- Everything below is DERIVED from the identifier just cleared and is rebuilt
  -- weekly from it, so leaving it would republish the wrong entity's facts.
  delete from public.tag_medical_codes c
   using _repair r
   where c.tag_id = r.tag_id and r.disposition = 'cleared' and c.source = 'wikidata';
  get diagnostics v_codes = row_count;

  -- run_tag_wikidata_hierarchy() writes exactly ('broader','auto') from P279/P361.
  delete from public.tag_relations t
   where t.relation_type = 'broader' and t.review_status = 'auto'
     and (t.source_tag_id in (select tag_id from _repair where disposition = 'cleared')
       or t.target_tag_id in (select tag_id from _repair where disposition = 'cleared'));
  get diagnostics v_rel = row_count;

  -- is_public rows are the hand-researched legal citations; never touch those.
  delete from public.tag_sources s
   using _repair r
   where s.tag_id = r.tag_id and r.disposition = 'cleared'
     and s.source_type in ('wikipedia','wikidata') and s.is_public is not true;
  get diagnostics v_src = row_count;

  raise notice 'wrong-entity repair: cleared % tags (short %, long %), % queued for review, % skipped as stale; deleted % medical codes, % broader edges, % wiki sources',
    v_cleared, v_short, v_long, v_review, v_missing, v_codes, v_rel, v_src;

  -- Guards cover only what this migration changed.
  if exists (select 1 from public.unified_tags u join _repair r on r.tag_id = u.id
              where r.disposition = 'cleared' and u.wikidata_id is not null) then
    raise exception 'wrong-entity repair: a cleared tag still carries a wikidata_id';
  end if;
  if exists (select 1 from public.tag_medical_codes c join _repair r on r.tag_id = c.tag_id
              where r.disposition = 'cleared' and c.source = 'wikidata') then
    raise exception 'wrong-entity repair: a cleared tag still carries wikidata-derived clinical codes';
  end if;
  if exists (select 1 from public.unified_tags u join _repair r on r.tag_id = u.id
              where r.disposition = 'review' and u.wikidata_id is null) then
    raise exception 'wrong-entity repair: a review-only tag was modified';
  end if;
end $repair$;
